    for (int i = 0; i < k; i++) {
        rev = (rev << 1) | (n & 1);
        n >>= 1;
    }
    return rev;
}

long long powMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long invMod(long long a) {
    return powMod(a, MOD - 2);
}

vector<long long> roots(int k, bool inverse) {
    long long root = powMod(ROOT, powMod(2, twoPow - k));
    if (inverse) {
        root = invMod(root);
    }
    vector<long long> rootsArr(k);
    if (k > 0) {
        rootsArr[k - 1] = root;
    }
    for (int i = k - 1; i > 0; i--) {
        rootsArr[i - 1] = (rootsArr[i] * rootsArr[i]) % MOD;
    }
    return rootsArr;
}

vector<long long> reorderArray(const vector<long long>& a, int k) {
    vector<long long> ans(a.size());
    for (size_t i = 0; i < a.size(); i++) {
        ans[bitReverse(i, k)] = a[i];
    }
    return ans;
}

vector<long long> ntt(vector<long long> coef, int k, bool inverse) {
